from pathlib import Path
import json,hashlib
work=Path('/tmp/meridian-ambience-candidate')
out=work/'evidence/ambience'
expected=json.loads((out/'expected.json').read_text())
def edit(file,old,new):
 p=work/file;s=p.read_text();assert old in s,old;p.write_text(s.replace(old,new))
edit('grandhall.html','if(vMat==78.||vMat==79.||vMat==80.||vMat==82.){vec4 effect=meridianAtmosphere(vMat,','float atmosphereMaterial=floor(vMat+.5);\n if(atmosphereMaterial==78.||atmosphereMaterial==79.||atmosphereMaterial==80.||atmosphereMaterial==82.){vec4 effect=meridianAtmosphere(atmosphereMaterial,')
edit('grandhall.html','if(vMat==81.){vec3 effect=meridianPlanet','if(atmosphereMaterial==81.){vec3 effect=meridianPlanet')
p=work/'scripts/meridian-celestial-qa.mjs'
p.write_text(p.read_text()+"\nassert.match(hall,/float atmosphereMaterial=floor\\(vMat\\+\\.5\\)/,'interpolated material IDs are rounded before effect dispatch');\n")
expected['grandhall.html']='a0361eed925b1cd4c7fc6e89836e7aab05a170102c97b633b99dc26808ec763f'
expected['scripts/meridian-celestial-qa.mjs']='df855af38a62e6b4403648957643f5e031f48a0c8b0dccc8392607d8056ad99e'
for file,digest in expected.items():assert hashlib.sha256((work/file).read_bytes()).hexdigest()==digest,file
(out/'expected.json').write_text(json.dumps(expected,indent=2))
p=out/'build-preview.py';s=p.read_text()
s=s.replace('innerWidth<700?31:28','innerWidth<700?38:34').replace('innerWidth<700?20:17','innerWidth<700?30:17').replace('perspective(.55,W/H,','perspective(innerWidth<700?.74:.55,W/H,')
s=s.replace('void main(){vec3 N=normalize(n),V=normalize(eye-p);if(!gl_FrontFacing)N=-N;','void main(){vec3 N=normalize(n),V=normalize(eye-p);if(!gl_FrontFacing)N=-N;float material=floor(m+.5);')
s=s.replace('if(m==','if(material==').replace('||m==','||material==').replace('metal=m==','metal=material==').replace('meridianAtmosphere(m,','meridianAtmosphere(material,')
p.write_text(s)
(out/'browser.cjs').write_text('const {chromium}=require(process.env.PLAYWRIGHT_MODULE);\nconst fs=require(\'node:fs\'),path=require(\'node:path\'),{pathToFileURL}=require(\'node:url\');\nconst out=\'evidence/ambience\',reports=[];\nconst save=()=>fs.writeFileSync(out+\'/browser.json\',JSON.stringify(reports,null,2));\nconst launch=()=>chromium.launch({headless:true,args:[\'--no-sandbox\',\'--use-angle=swiftshader\',\'--enable-unsafe-swiftshader\',\'--disable-dev-shm-usage\']});\n(async()=>{\n for(const [kind,width,height,night]of[[\'preview\',1100,900,1],[\'preview\',390,844,1],[\'preview\',320,844,1],[\'hall\',1100,900,1],[\'hall\',390,844,1],[\'hall\',320,844,1],[\'commons\',390,844,1],[\'commons\',320,844,1],[\'hall\',390,844,0]]){\n  const browser=await launch(),page=await browser.newPage({viewport:{width,height},deviceScaleFactor:1});\n  const report={kind,width,height,night,errors:[]};reports.push(report);save();\n  page.on(\'pageerror\',e=>{report.errors.push(e.message);save();});\n  page.on(\'console\',m=>{if(m.type()===\'error\'){report.errors.push(m.text());save();}});\n  try{\n   const url=kind===\'preview\'?pathToFileURL(path.resolve(out,\'preview.html\')).href:\'http://127.0.0.1:4188/\'+(kind===\'hall\'?\'grandhall.html?bay=AR-03\':\'?room=commons&work=meridian-hill-observatory&placement=0\');\n   report.url=url;await page.goto(url,{waitUntil:\'load\',timeout:60000});report.loaded=true;save();\n   await page.waitForFunction(kind===\'preview\'?\'window.meridianReady===true\':kind===\'hall\'?\'window.hallReady===true\':\'window.HOBBY_HOUSE?.state.room==="commons"\',null,{timeout:60000});\n   report.ready=true;save();\n   if(kind===\'hall\')await page.evaluate(n=>{state.evening=!!n;state.night=n;},night);\n   if(kind===\'commons\')await page.evaluate(n=>{setMood(n?\'night\':\'day\',{persist:false,immediate:true});},night);\n   await page.waitForTimeout(1700);\n   report.data=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth,webgl:!!document.getElementById(\'world\')?.getContext(\'webgl2\')||!!document.getElementById(\'scene\')?.getContext(\'webgl2\'),preview:window.meridianPreview?.state,commons:window.HOBBY_HOUSE?.state,lighting:window.RAILWAY?.state.mood}));save();\n   await page.screenshot({path:out+\'/\'+kind+\'-\'+width+\'-\'+night+\'.png\',timeout:60000});report.screenshot=true;save();\n   if(kind===\'preview\'){\n    await page.locator(\'#sky\').click();await page.waitForTimeout(2400);await page.screenshot({path:out+\'/preview-detail-\'+width+\'.png\',timeout:60000});\n    await page.locator(\'#pause\').click();const t=await page.evaluate(()=>meridianPreview.state.time);await page.waitForTimeout(300);report.pauseFrozen=t===await page.evaluate(()=>meridianPreview.state.time);\n    await page.locator(\'#home\').click();await page.waitForTimeout(1500);\n   }\n  }catch(e){report.errors.push(e.stack||e.message);save();try{await page.screenshot({path:out+\'/\'+kind+\'-\'+width+\'-error.png\',timeout:5000});}catch{} }\n  finally{save();await browser.close();}\n }\n const browser=await launch(),page=await browser.newPage({viewport:{width:390,height:844},reducedMotion:\'reduce\'}),report={kind:\'reduced\',errors:[]};reports.push(report);\n try{await page.goto(pathToFileURL(path.resolve(out,\'preview.html\')).href);await page.waitForFunction(\'window.meridianReady\',null,{timeout:60000});const t=await page.evaluate(()=>meridianPreview.state.time);await page.waitForTimeout(500);report.frozen=t===await page.evaluate(()=>meridianPreview.state.time);}catch(e){report.errors.push(e.message);}finally{save();await browser.close();}\n if(reports.some(r=>r.errors.length||r.data?.overflow||r.frozen===false||r.pauseFrozen===false))process.exitCode=1;\n})();\n')
